<?php
require_once __DIR__.'/includes/config.php'; require_login(); require_permission('products');
$uid=(int)$_SESSION['user_id'];
$q=$pdo->prepare('SELECT id,name,sku,quantity,low_stock_threshold,cost_price,selling_price FROM products WHERE user_id=? AND quantity<=low_stock_threshold ORDER BY quantity ASC,name ASC');
$q->execute([$uid]); $rows=$q->fetchAll();
if(($_GET['export']??'')==='csv') { header('Content-Type: text/csv; charset=utf-8'); header('Content-Disposition: attachment; filename="kasuwalink-low-stock-'.date('Y-m-d').'.csv"'); $out=fopen('php://output','w'); fputcsv($out,['Product','SKU','Current quantity','Alert threshold','Suggested reorder quantity','Unit cost NGN','Estimated reorder cost NGN']); foreach($rows as $r){$suggest=max(0,(int)$r['low_stock_threshold']*2-(int)$r['quantity']);fputcsv($out,[$r['name'],$r['sku'],$r['quantity'],$r['low_stock_threshold'],$suggest,$r['cost_price'],$suggest*(float)$r['cost_price']]);} fclose($out); exit; }
$pageTitle='Low-stock alerts'; require __DIR__.'/includes/header.php'; ?>
<div class="page-heading"><div><div class="text-secondary small">INVENTORY ALERTS</div><h1 class="h3 fw-bold mb-1">Low-stock alerts</h1><p class="muted mb-0">Products at or below their configured stock threshold.</p></div><div class="d-flex gap-2"><a class="btn btn-outline-primary" href="low_stock.php?export=csv">Export CSV</a><a class="btn btn-primary" href="products.php">Manage products</a></div></div>
<div class="alert alert-info">Suggested reorder quantity is a planning estimate (twice the threshold minus current stock), not an automatic purchase order.</div>
<div class="card"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 fw-bold mb-0">Items requiring attention</h2><span class="badge text-bg-warning"><?=count($rows)?> items</span></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Product</th><th>SKU</th><th>Current stock</th><th>Alert at</th><th>Suggested reorder</th><th>Estimated cost</th><th></th></tr></thead><tbody><?php foreach($rows as $r): $suggest=max(0,(int)$r['low_stock_threshold']*2-(int)$r['quantity']); ?><tr><td class="fw-semibold"><?=e($r['name'])?></td><td><?=e($r['sku']??'—')?></td><td><span class="badge text-bg-danger"><?=(int)$r['quantity']?></span></td><td><?=(int)$r['low_stock_threshold']?></td><td><?=$suggest?></td><td><?=money($suggest*(float)$r['cost_price'])?></td><td><a class="btn btn-sm btn-outline-primary" href="edit_product.php?id=<?=(int)$r['id']?>">Update stock</a></td></tr><?php endforeach; ?></tbody></table><?php if(!$rows): ?><div class="empty-state"><h3 class="h6">All clear — no low-stock products</h3><p class="mb-0">Your current inventory is above its alert thresholds.</p></div><?php endif; ?></div></div></div>
<?php require __DIR__.'/includes/footer.php'; ?>
